import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        PriorityQueue<Long> heap = new PriorityQueue<>(Collections.reverseOrder());  // values given a minus sign
        long balance = 0;
        for (int i = 0; i < n; i++) {
            long v = nextLong();
            balance -= v;
            heap.add(v);
            // Prefix not positive: flip the largest negated value back to plus.
            if (balance <= 0) balance += 2 * heap.poll();
        }
        System.out.println(heap.size());
    }
}

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

type maxHeap []int64

func (h maxHeap) Len() int           { return len(h) }
func (h maxHeap) Less(i, j int) bool { return h[i] > h[j] }
func (h maxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x any)        { *h = append(*h, x.(int64)) }
func (h *maxHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	h := &maxHeap{} // values currently given a minus sign
	balance := int64(0)
	for i := 0; i < n; i++ {
		v := nextInt()
		balance -= v
		heap.Push(h, v)
		// Prefix not positive: flip the largest negated value back to plus.
		if balance <= 0 {
			balance += 2 * heap.Pop(h).(int64)
		}
	}
	fmt.Println(h.Len())
}
